examples.code:
lead: note("c4 e4 g4 b4").s("sawtooth").tap("line")
capture("riff", "lead/line", { window: "1b..5b" })
echo: recall("riff").add(note(12)).s("triangle").late(0.25).gain(0.5)

// @daw bars=8
setcpm(120/4)
//@ 1-4 section: *intro*, the bell alone | form:intro
//@ 5-8 section: the bass answers | form:drop
bell: n("<0 2 4 3>*2").scale("C4:minor").s("triangle").decay(0.2) //@ 1-8 motif: bell cell | MOT-01 | id=cell
bass: n("<0 -2>").scale("C2:minor").s("sawtooth").lpf(600).mask("<0 0 0 0 1 1 1 1>") //@ 5-8 call-response @bell~bass: the bass answers the cell | INT-01 | answers:cell

// @daw bars=8
setcpm(120/4)
//@ M1@1 -> M1@7 callback @lead: the opening cell returns | FS-05
//@ 3-4 => 7-8 foreshadow @lead: tease, then the full line | FS-01
lead: n("<[0 2 4 ~] [~ ~ ~ ~] [0 ~ ~ ~] [~ ~ ~ ~] [0 2 4 3] [4 3 2 ~] [0 2 4 ~] [0 2 4 3]>").scale("G4:minor").s("square").lpf(2000).decay(0.15)

// The Tempo knob mirrors this setcpm. Touching the knob overrides it; the Program button next to it hands control back.
setcpm(128.8 / 4)
$: s("bd ~ ~ bd, hh*8").bank("RolandTR909")

