examples.code:
// strudelCraft.atoms.extract(code) turns repeated strings into atoms and the references back; inline(code) undoes it
$: s("bd*4 sd")
$: s("bd*4 sd").gain(0.8)

setcpm(140/4)
atoms.import("pack:glyphcore/edm:atoms-edm-depth")
// bounce in place: capture bars 1-2 of the FM bass as audio (CLI: strudel capture IN --name bounce -o bounce.wav;
// site: the capture picker), then load bounce.wav as a sample and process it again (a second rack): resampling
bass: note(atoms.ed.growl).hook("serialFM").mask("<1 1 0 0>")
capture("bounce", "bass", { window: "1b..3b", what: ["audio"] })

